{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/error-page.json
    A page that tells the visitor something went wrong: an icon or a big code, a heading, a sentence and the way back. Axes: layout (centered, split: the picture beside the text), code (show, hide), actions mode (one, two), tone.
    Props (p): id, title, text, status, actions, level, layout, code, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_text = ($p['text'] ?? null)}
{var $v_status = ($p['status'] ?? null)}
{var $v_actions = ($p['actions'] ?? null)}
{var $v_level = ($p['level'] ?? 1)}
{var $v_layout = ($p['layout'] ?? 'centered')}
{var $v_code = ($p['code'] ?? 'show')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $f_2}
  {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => '4/3']])|noescape}
{/capture}
{capture $c_3}
  {if ui_t(ui_eq($v_code, 'show'))}
    {capture $c_1}
      {=ui_text($v_status)}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => '4xl', 'Weight' => 'bold', 'Class' => ui_s(ui_cnv(['text-8xl text-muted-foreground', (ui_t(ui_eq($v_layout, 'split')) ? '' : 'text-center')])), 'Attrs' => ui_attrs(['data-testid', 'error-code'])], 'children' => $c_1])|noescape}
  {/if}
  {=ui_include('blocks/action-group.latte', ['p' => ['primary' => ui_get($v_actions, ['cta']), 'primaryHref' => ui_get($v_actions, ['href']), 'secondary' => (ui_t(ui_eq(ui_get($v_actions, ['mode']), 'two')) ? ui_get($v_actions, ['secondary']) : null), 'secondaryHref' => ui_get($v_actions, ['secondaryHref']), 'align' => (ui_t(ui_eq($v_layout, 'split')) ? 'start' : 'center')]])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_text, 'heading' => ['level' => $v_level], 'layout' => (ui_t(ui_eq($v_layout, 'split')) ? 'split' : 'stack'), 'media' => ['show' => ui_eq($v_layout, 'split')], 'align' => (ui_t(ui_eq($v_layout, 'split')) ? 'start' : 'center'), 'tone' => $v_tone, 'density' => 'roomy', 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_2], 'children' => $c_3])|noescape}
